mapper.select:

WHERE r.student_id = #{studentId}

    AND r.record_time >= #{startDate}
    AND r.record_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)


    AND os.course_code = #{courseCode}


    AND os.environment_code = #{environmentCode}


    AND r.observation_session_id = #{observationSessionId}

ORDER BY r.record_time DESC, r.id DESC, at.code
